  'Anybody with the address can open it, and search engines can find it. Nothing else about your account is shown.': 'Jeder mit der Adresse kann es öffnen, und Suchmaschinen finden es. Sonst wird nichts von deinem Konto gezeigt.',
  'Anyone around for a coffee and a collab? Keen to shoot some content around the city.': 'Jemand da für einen Kaffee und eine Kollaboration? Hätte Lust, ein bisschen Content in der Stadt zu drehen.',
  'Anyone who signs up with this link is credited to you automatically.': 'Jeder, der sich über diesen Link anmeldet, wird dir automatisch gutgeschrieben.',
  'Anything a person wrote stays exactly as they wrote it': 'Alles, was ein Mensch geschrieben hat, bleibt genau so, wie er es geschrieben hat',
  'Anything a person wrote stays exactly as they wrote it: messages, captions, challenge briefs and names.': 'Alles, was ein Mensch geschrieben hat, bleibt genau so: Nachrichten, Bildunterschriften, Challenge-Briefings und Namen.',
