  'Approve': 'Freigeben',
  'Approve all': 'Alle freigeben',
  'Approve all {n}': 'Alle {n} freigeben',
  'Approve all {n} drafts? Each one is added to the creator\'s balance, and their payout window opens.': 'Alle {n} Entwürfe freigeben? Jeder wird dem Guthaben gutgeschrieben und das Auszahlungsfenster öffnet sich.',
  'Approve all {n} drafts? Each one raises its invoice for the creator. You can still stop an invoice from Rewards.': 'Alle {n} Entwürfe freigeben? Jeder erzeugt die Rechnung des Creators. Eine Rechnung kannst du unter Belohnungen noch stoppen.',
  'Approved': 'Freigegeben',
  'Approved, to pay': 'Freigegeben, zu zahlen',
  'Approving a month adds it to each balance. For {d} days after the month ends, a VIP can take cash (from {a}) or a Tryp.com voucher (any amount). Otherwise it keeps growing.': 'Die Freigabe eines Monats schreibt ihn jedem Guthaben gut. {d} Tage nach Monatsende kann ein VIP sich Geld auszahlen lassen (ab {a}) oder einen Tryp.com-Gutschein nehmen (beliebiger Betrag). Sonst wächst es weiter.',
  'Approving a statement adds it to the creator\'s balance and opens their payout window: cash once the balance reaches the threshold, or a Tryp.com voucher for any amount. Their invoice is raised when they ask for cash. Late corrections go on next month\'s statement or as a balance correction in Balances.': 'Die Freigabe einer Abrechnung schreibt sie dem Guthaben gut und öffnet das Auszahlungsfenster: Geld, sobald das Guthaben die Schwelle erreicht, oder ein Tryp.com-Gutschein für jeden Betrag. Die Rechnung entsteht, wenn Geld angefordert wird. Spätere Korrekturen kommen in die Abrechnung des nächsten Monats oder als Guthabenkorrektur unter Guthaben.',
  'Approving a statement raises the creator\'s invoice and counts as approving it. A creator with no payment details is approved anyway and their invoice follows the day they save them. Late corrections go on next month\'s statement, never by reopening a month that is paid.': 'Mit der Freigabe einer Abrechnung wird die Rechnung des Creators erstellt und gilt als freigegeben. Ein Creator ohne Zahlungsdaten wird trotzdem freigegeben, seine Rechnung folgt an dem Tag, an dem er sie speichert. Nachträgliche Korrekturen kommen in die Abrechnung des nächsten Monats, ein bezahlter Monat wird nie wieder geöffnet.',
  'Archive': 'Archivieren',
  'Arrange the board': 'Board anordnen',
