  'Arrow': 'Pfeil',
  'Arrow keys change month · T for today': 'Pfeiltasten wechseln den Monat · T für heute',
  'As {c} is under 18, the terms also need the agreement of a parent or legal guardian. Please read them below, then confirm in your own name.': 'Da {c} unter 18 ist, brauchen die Bedingungen auch die Zustimmung eines Elternteils oder gesetzlichen Vormunds. Bitte lies sie unten und bestätige mit deinem Namen.',
  'As a creator': 'Als Creator',
