  'As many as they like': 'So viele sie wollen',
  'As you are under 18, your parent or guardian confirms the terms too. Send them this link; they read the terms and confirm in a minute, no account needed.': 'Da du unter 18 bist, bestätigt auch dein Elternteil oder Vormund die Bedingungen. Schick ihm diesen Link; Lesen und Bestätigen dauert eine Minute, ohne Konto.',
