  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice.': 'Am Ende jedes Monats lesen wir deine Aufrufe ein letztes Mal, erstellen deine Abrechnung und, sobald sie freigegeben ist, deine Rechnung.',
  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice. Small amounts below the minimum payout carry over to the next month.': 'Am Ende jedes Monats lesen wir deine Views ein letztes Mal aus, erstellen deine Abrechnung und, sobald sie freigegeben ist, deine Rechnung. Kleine Beträge unter der Mindestauszahlung werden in den nächsten Monat übertragen.',
