  'Bonuses are rules, not hand payments. The month-end close works each one out for every VIP, and you check the result before anything is approved. You can set bonuses for each creator, for the ranking in this market, or for the ranking across every VIP.': 'Boni sind Regeln, keine Handzahlungen. Der Monatsabschluss berechnet jeden für jeden VIP, und du prüfst das Ergebnis, bevor etwas freigegeben wird. Du kannst Boni für jeden Creator, für das Ranking in diesem Markt oder für das Ranking über alle VIPs festlegen.',
  'Bonuses running now': 'Laufende Boni',
  'Booking both in one trip usually comes out cheaper than booking them separately. Show the total per person.': 'Beides zusammen zu buchen ist meistens günstiger als getrennt. Zeig den Gesamtpreis pro Person.',
