  'Challenge': 'Challenge',
  'Challenge briefs and rules are translated automatically the first time a creator reads them in this language. Check them here, and correct anything that reads wrong. Your version is kept and shown instead.': 'Briefings und Regeln von Challenges werden automatisch übersetzt, wenn ein Creator sie zum ersten Mal in dieser Sprache liest. Prüfe sie hier und korrigiere, was falsch klingt. Deine Version wird gespeichert und stattdessen angezeigt.',
