  'Check it again. It is six characters after the year, and the letters O and I are never used, so a nought is a zero and a one is a one. If it still does not come up, this was not issued by Tryp.com.': 'Prüf ihn noch einmal. Nach der Jahreszahl folgen sechs Zeichen, und die Buchstaben O und I kommen nie vor – eine Null ist also eine Null und eine Eins ist eine Eins. Wenn dann immer noch nichts erscheint, wurde das nicht von Tryp.com ausgestellt.',
