  'I agree to the {terms} and {privacy}, and to represent Tryp.com honestly in my content.': 'Ich stimme den {terms} und der {privacy} zu und verpflichte mich, Tryp.com in meinen Inhalten ehrlich darzustellen.',
  'I am {c}\'s parent or legal guardian. I have read the {t} and I agree to them for {c}.': 'Ich bin Elternteil oder gesetzlicher Vormund von {c}. Ich habe die {t} gelesen und stimme ihnen für {c} zu.',
