  'I don\'t want to take part': 'Ich möchte nicht teilnehmen',
  'I film budget city breaks around my 9 to 5, and when I\'m not travelling I\'m climbing or hunting down the best coffee in town.': 'Ich filme günstige Städtetrips neben meinem Bürojob, und wenn ich nicht unterwegs bin, klettere ich oder suche den besten Kaffee der Stadt.',
  'I have already added it': 'Ich habe es schon hinzugefügt',
  'I have read and agree to the {t}, and my parent or guardian named above agrees too.': 'Ich habe die {t} gelesen und stimme ihnen zu, und meine oben genannten Eltern oder mein Vormund stimmen ebenfalls zu.',
  'I have read and agree to the {t}.': 'Ich habe gelesen und stimme zu: {t}.',
  'I have read and agree to the {t}. I will send my parent or guardian named above the link to confirm it.': 'Ich habe die {t} gelesen und stimme zu. Ich schicke meinem oben genannten Elternteil oder Vormund den Link zur Bestätigung.',
  'I have read the {t} and I agree to it. I sign it electronically with my name above.': 'Ich habe „{t}“ gelesen und stimme zu. Ich unterschreibe elektronisch mit meinem Namen oben.',
  'I have read the VIP terms and I agree to them.': 'Ich habe die VIP-Bedingungen gelesen und stimme ihnen zu.',
