  'I make': 'Ich mache',
  'I make short travel videos about the places I go and the things worth stopping for. I am part of the Tryp.com Content Creator Community, where creators from around the world make work for monthly challenges.': 'Ich mache kurze Reisevideos über die Orte, an die ich reise, und alles, wofür sich ein Stopp lohnt. Ich bin Teil der Tryp.com Content Creator Community, in der Creator aus aller Welt Inhalte für monatliche Challenges erstellen.',
  'I\'ll do this later': 'Das mache ich später',
  'I\'m in Lisbon the same week. Fancy shooting a couple of reels around Alfama, or just a coffee?': 'Ich bin dieselbe Woche in Lissabon. Lust, ein paar Reels in Alfama zu drehen – oder einfach auf einen Kaffee?',
  'I\'m planning a Balkans road trip next spring and would love to team up with anyone heading that way.': 'Ich plane nächstes Frühjahr einen Roadtrip durch den Balkan und würde mich über Gesellschaft freuen.',
  'Icon': 'Symbol',
  'Identity': 'Identität',
  'If an account exists for {email}, you\'ll receive a reset link shortly. Check your spam folder too.': 'Falls es ein Konto für {email} gibt, bekommst du gleich einen Link zum Zurücksetzen. Schau auch in deinem Spam-Ordner nach.',
  'If it keeps failing, please let us know rather than waiting.': 'Wenn es weiter nicht klappt, sag uns bitte Bescheid, statt zu warten.',
  'If it still will not read, try the digital pass instead: a screenshot straight from Apple Wallet or the airline app scans far more reliably than a photo of a printed one. Otherwise close this and type the flight in.': 'Wenn es immer noch nicht klappt, nimm die digitale Bordkarte: Ein Screenshot direkt aus Apple Wallet oder der App der Airline wird viel zuverlässiger erkannt als ein Foto einer ausgedruckten. Sonst schließ das hier und trag den Flug von Hand ein.',
  'If the month ended now: {n} would earn it, {a} in all.': 'Wenn der Monat jetzt endete: {n} würden ihn verdienen, insgesamt {a}.',
  'If you win before we have these, your prize waits until we do. You can add them any time from Settings.': 'Wenn du gewinnst, bevor wir die haben, wartet dein Preis, bis wir sie haben. Du kannst sie jederzeit in den Einstellungen nachtragen.',
  'If your streak is at risk, we’ll nudge you around 6pm to play before midnight.': 'Wenn deine Serie in Gefahr ist, erinnern wir dich gegen 18 Uhr, noch vor Mitternacht zu spielen.',
