  'Issued by chat. The code is in your messages with the team.': 'Per Chat verschickt. Der Code steht in deinen Nachrichten mit dem Team.',
  'It appears for everyone who entered, once the challenge has ended - never while it is running.': 'Sie erscheint allen Teilnehmenden, sobald die Challenge beendet ist, nie während sie läuft.',
  'It behaves like': 'Es verhält sich wie',
  'It builds up through the period, so being halfway to the goal halfway through is on track.': 'Er baut sich über den Zeitraum auf – halb am Ziel zur Halbzeit liegt also im Plan.',
  'It cannot end before it starts.': 'Es kann nicht enden, bevor es anfängt.',
  'It goes out of the tracker along with the hook and any notes on it. A synced video comes back on the next sync; one added by hand does not.': 'Es verschwindet aus dem Tracker, samt Hook und allen Notizen. Ein synchronisiertes Video kommt beim nächsten Sync zurück, ein von Hand hinzugefügtes nicht.',
  'It is a level, not a total, so it is held against the goal itself all the way through.': 'Es ist ein Niveau, keine Summe, daher wird es die ganze Zeit direkt mit dem Ziel verglichen.',
  'It is already in {c}, which is this challenge.': 'Es ist schon in {c}, also in dieser Challenge.',
  'It is already in {c}. A video can only count in one challenge.': 'Es ist schon in {c}. Ein Video kann nur in einer Challenge zählen.',
  'It is okay': 'Ist in Ordnung',
