  'It is posted in the VIP announcements room': 'Es wird im VIP-Ankündigungsraum gepostet',
  'It is removed from the challenge log and from every programme average that counted it. There is no undo.': 'Es wird aus dem Challenge-Protokoll und aus jedem Programm-Durchschnitt entfernt, der es mitgezählt hat. Das lässt sich nicht rückgängig machen.',
  'It keeps coming back each time they open the app until they answer or say no.': 'Sie erscheint bei jedem Öffnen der App wieder, bis sie antworten oder Nein sagen.',
