  'On the last day of each month we take a final reading of your views, and your statement appears here once the team has checked it. Your invoice follows.': 'Am letzten Tag jedes Monats lesen wir deine Views ein letztes Mal aus, und deine Abrechnung erscheint hier, sobald das Team sie geprüft hat. Deine Rechnung folgt.',
  'On the last day of each month we take a final reading of your views. Your statement appears here once the team has checked it, and your invoice follows.': 'Am letzten Tag jedes Monats lesen wir deine Aufrufe ein letztes Mal. Deine Abrechnung erscheint hier, sobald das Team sie geprüft hat, und deine Rechnung folgt.',
