  'Once you connect with other creators they\'ll appear here. Head to a profile or the Connections page to start building your network.': 'Sobald du dich mit anderen Creators vernetzt, erscheinen sie hier. Geh auf ein Profil oder auf die Kontakte-Seite, um dein Netzwerk aufzubauen.',
  'Once you enter a challenge, your videos appear here and on your portfolio automatically.': 'Sobald du an einer Challenge teilnimmst, erscheinen deine Videos automatisch hier und in deinem Portfolio.',
