  'One': 'Eins',
  'One a day keeps the streak alive.': 'Einmal am Tag hält die Serie am Leben.',
  'One goal comes from {q}': 'Ein Ziel stammt aus {q}',
  'One goal here is {q}\'s goal shared across its months, rising gently as the quarter goes on.': 'Ein Ziel hier ist das Ziel für {q}, auf die Monate verteilt und im Lauf des Quartals sanft ansteigend.',
  'One goal here is the monthly goals added together. Set a quarter goal to replace it.': 'Ein Ziel hier ist die Summe der Monatsziele. Lege ein Quartalsziel fest, um es zu ersetzen.',
  'One goal is the months added up': 'Ein Ziel ist die Monate zusammengerechnet',
  'One line per creator per month: name, month, views, and optionally the amount and the rate. Paste straight from a spreadsheet.': 'Eine Zeile pro Creator und Monat: Name, Monat, Aufrufe und optional Betrag und Satz. Direkt aus einer Tabelle einfügen.',
  'One line under the title': 'Eine Zeile unter dem Titel',
  'One line, shown under the market name.': 'Eine Zeile, unter dem Marktnamen angezeigt.',
  'One link for every VIP, in every market, and it never expires. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Ein Link für alle VIPs in allen Märkten, und er läuft nie ab. Sie registrieren sich wie gewohnt, werden in der Bewerbungsliste als VIP markiert und kommen ins VIP-Programm ihres Marktes, wenn du sie freigibst.',
  'One link for every VIP, in every market. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Ein Link für alle VIPs in allen Märkten. Sie melden sich wie gewohnt an, erscheinen in der Bewerbungsliste als VIP markiert und kommen nach deiner Freigabe in das VIP-Programm ihres eigenen Marktes.',
  'One moment.': 'Einen Moment.',
  'One moment…': 'Einen Moment…',
  'One month': 'Ein Monat',
  'One of your {n} VIP videos this month. Post it on your own account, then add the link on your VIP page so its views start counting.': 'Eines deiner {n} VIP-Videos in diesem Monat. Poste es auf deinem eigenen Account und füge den Link auf deiner VIP-Seite hinzu, damit seine Aufrufe zählen.',
  'One other market also covers {country}. The team will sort that out with you after you join.': 'Ein weiterer Markt deckt ebenfalls {country} ab. Das klärt das Team mit dir, nachdem du beigetreten bist.',
  'One puzzle a day': 'Ein Rätsel am Tag',
  'One rate for every view. Add a step to pay more past a number of views.': 'Eine Rate für jeden Aufruf. Füge eine Stufe hinzu, um ab einer Anzahl mehr zu zahlen.',
  'One tap and it is done': 'Ein Tipp und es ist erledigt',
  'One thing people should ask you about': 'Eine Sache, nach der dich Leute fragen sollten',
  'One travel game a day keeps a run alive - any of the daily puzzles, or any of the practice modes. Miss a day and a freeze covers it, if you have one left.': 'Ein Reisespiel am Tag hält eine Serie am Leben – eines der täglichen Rätsel oder ein Übungsmodus. Verpasst du einen Tag, fängt ein Freeze ihn auf, falls du noch einen hast.',
  'One video with {n} views': 'Ein Video mit {n} Aufrufen',
