  'Only {m}': 'Nur {m}',
  'Only admins see this preview. Each one uses your name and a sample challenge; open one to check the certificate, the Instagram story and both downloads. Drafts are not given to anybody.': 'Nur Admins sehen diese Vorschau. Jedes nutzt deinen Namen und eine Beispiel-Challenge; öffne eines, um das Zertifikat, die Instagram-Story und beide Downloads zu prüfen. Entwürfe werden an niemanden vergeben.',
  'Only creators in the markets you pick': 'Nur Creator in den gewählten Märkten',
  'Only creators who chose to be on the map.': 'Nur Creator, die auf der Karte erscheinen wollten.',
  'Only for the VIP creators of this market and the team.': 'Nur für die VIP-Creator dieses Markts und das Team.',
  'Only the creator can save this': 'Nur der Creator kann das speichern',
  'Only the Tryp.com Team sees this. Choose which admin alerts you want to receive, and jump into the admin tools.': 'Das sieht nur das Tryp.com-Team. Wähl aus, welche Admin-Hinweise du bekommen willst, und spring direkt in die Admin-Werkzeuge.',
  'Only TikTok, Instagram, YouTube and Facebook links carry a view count we can read.': 'Nur Links von TikTok, Instagram, YouTube und Facebook enthalten eine Viewzahl, die wir lesen können.',
  'Only VIP creators and the team can see these. Ask anything, share what is working, and meet the other VIPs.': 'Nur VIP-Creator und das Team sehen diese. Frag alles, teile, was funktioniert, und lerne die anderen VIPs kennen.',
  'Only VIP creators and the team can see these. This is where the WhatsApp group lives now.': 'Nur VIP-Creators und das Team können sie sehen. Hier lebt jetzt die WhatsApp-Gruppe.',
