  'Thank-you message': 'Danke-Nachricht',
  'Thanks so much for your interest in the Tryp.com Content Creator Community. Unfortunately your application was not successful this time. We\'re sorry, and we truly appreciate you taking the time to apply.': 'Vielen Dank für dein Interesse an der Tryp.com Content-Creator-Community. Leider war deine Bewerbung diesmal nicht erfolgreich. Das tut uns leid, und wir wissen es sehr zu schätzen, dass du dir die Zeit genommen hast.',
