  'That email already has an account. Log in with your password, or use Continue with Google if that is how you joined. Forgotten your password? Reset it from the log in page.': 'Zu dieser E-Mail-Adresse gibt es schon ein Konto. Melde dich mit deinem Passwort an oder nutze „Weiter mit Google“, falls du dich so angemeldet hast. Passwort vergessen? Setz es auf der Anmeldeseite zurück.',
  'That host is not one of the four the tracker knows. It will still be saved.': 'Dieser Host ist keiner der vier, die der Tracker kennt. Es wird trotzdem gespeichert.',
