  'That makes you {n}, and the community is for {min} and over. You are welcome to apply again once you are old enough.': 'Damit bist du {n}, und die Community ist ab {min}. Du kannst dich gern wieder bewerben, sobald du alt genug bist.',
  'That question is not here': 'Diese Frage gibt es hier nicht',
