  'We are all in the community. Press a name to open a private chat.': 'Wir sind alle in der Community. Tippe auf einen Namen, um einen privaten Chat zu öffnen.',
  'We are in the community too. Connect or message any of us.': 'Wir sind auch in der Community. Vernetze dich oder schreib uns einfach.',
  'We cannot ask again from here once a device has said no.': 'Wenn ein Gerät einmal Nein gesagt hat, können wir von hier aus nicht noch einmal fragen.',
