  'We do not recognise that VIP link. Check you copied all of it, or ask the team to send it again. You can still sign up as a creator below.': 'Wir erkennen diesen VIP-Link nicht. Prüfe, ob du ihn vollständig kopiert hast, oder bitte das Team, ihn erneut zu senden. Du kannst dich unten trotzdem als Creator registrieren.',
  'We email a reset link to the address above.': 'Wir schicken einen Link zum Zurücksetzen an die Adresse oben.',
  'We filled in what your profile already says. Answer what you like, and your card builds itself as you go.': 'Wir haben übernommen, was in deinem Profil schon steht. Beantworte, was du magst – deine Karte baut sich nebenbei auf.',
  'We filled in what your profile already says. Change anything, skip anything, and your card is ready.': 'Wir haben übernommen, was in deinem Profil schon steht. Ändere oder überspringe, was du willst, dann ist deine Karte fertig.',
  'We have sent you a confirmation link. Open it, then log in and we will take you through the rest.': 'Wir haben dir einen Bestätigungslink geschickt. Öffne ihn, melde dich an, und wir führen dich durch den Rest.',
  'We have your age as {n}. Add your date of birth and it will stay right on your birthday.': 'Wir haben dein Alter mit {n} gespeichert. Trag dein Geburtsdatum ein, dann stimmt es auch an deinem Geburtstag.',
  'We match them by themselves. Its views count once, and you both get the points.': 'Wir ordnen sie automatisch zu. Die Views zählen einmal und ihr bekommt beide die Punkte.',
  'We post new positions here first. Keep creating great content and you\'ll be top of mind.': 'Neue Stellen posten wir zuerst hier. Mach weiter guten Content, dann denken wir zuerst an dich.',
  'We record your name, the time, and the IP address and device you confirm from, as evidence of your agreement. Questions: {e}': 'Wir speichern deinen Namen, die Uhrzeit sowie die IP-Adresse und das Gerät, von dem du bestätigst, als Nachweis deiner Zustimmung. Fragen: {e}',
  'We updated the {t}': 'Wir haben aktualisiert: {t}',
  'We want your ideas for challenges, features and anything else.': 'Wir wollen deine Ideen für Challenges, Funktionen und alles andere.',
  'We\'re having trouble reaching the server. Your connection might be slow. Give it another try.': 'Wir erreichen den Server gerade nicht. Vielleicht ist deine Verbindung langsam. Versuch es noch einmal.',
  'Weak signal: loading the essentials first': 'Schwacher Empfang: das Wichtigste zuerst',
