  'When 3 creators you refer join and take part in a challenge, you earn a €20 Tryp.com voucher. All referrals are verified by the Tryp.com team to make sure they\'re genuine, active creators.': 'Wenn 3 von dir geworbene Creator beitreten und an einer Challenge teilnehmen, bekommst du einen Tryp.com-Gutschein über 20 €. Alle Empfehlungen werden vom Tryp.com-Team geprüft, damit es wirklich echte, aktive Creator sind.',
