  'You are all up to date.': 'Du bist auf dem neuesten Stand.',
  'You are applying to join the Tryp.com team as {role}. Somebody on the team still has to approve you.': 'Du bewirbst dich als {role} für das Tryp.com-Team. Jemand aus dem Team muss dich noch freigeben.',
  'You are applying to join the Tryp.com team. Somebody on the team still has to approve you.': 'Du bewirbst dich für das Tryp.com-Team. Jemand aus dem Team muss dich noch freigeben.',
  'You are back with the community creators': 'Du bist wieder bei den Community-Creators',
  'You are both in {where} at the same time next month.': 'Ihr seid nächsten Monat gleichzeitig in {where}.',
  'You are both mostly on {platform}.': 'Ihr seid beide hauptsächlich auf {platform}.',
  'You are going to {country}. {name} has been.': 'Du fährst nach {country}. {name} war schon da.',
  'You are here': 'Du bist hier',
  'You are hidden from the public pages, so this map hides you too. Turn that on to choose.': 'Du bist auf den öffentlichen Seiten ausgeblendet, daher blendet dich auch diese Karte aus. Schalte das ein, um zu wählen.',
  'You are hidden from this map.': 'Du bist auf dieser Karte ausgeblendet.',
  'You are in': 'Du bist dabei',
  'You are in an app\'s built-in browser, which cannot add anything to your home screen. Open Tryp.com in Safari or Chrome and this will take ten seconds.': 'Du bist im eingebauten Browser einer App, der nichts zum Homescreen hinzufügen kann. Öffne Tryp.com in Safari oder Chrome, dann dauert es zehn Sekunden.',
  'You are in the prize places, so this one goes to someone else.': 'Du bist auf einem Preisrang, deshalb geht dieser an jemand anderen.',
  'You are in the worldwide community as well. A market is where your briefs come from, not a smaller room you go into instead.': 'Du bist auch in der weltweiten Community. Ein Markt ist die Quelle deiner Briefings, nicht ein kleinerer Raum, in den du stattdessen gehst.',
  'You are in these.': 'In diesen bist du drin.',
  'You are joining the Tryp.com Content Creator Community, a global community of travel creators who make great content, compete in challenges and earn real rewards.': 'Du trittst der Tryp.com Content Creator Community bei – einer weltweiten Community von Reise-Creatorn, die guten Content machen, in Challenges antreten und echte Prämien verdienen.',
  'You are joining the VIP creators': 'Du wirst VIP-Creator',
  'You are left out of the public map, the creators strip and the wall of fame. Fellow creators can still find you in the app.': 'Du erscheinst nicht auf der öffentlichen Karte, im Creator-Band und in der Wall of Fame. Andere Creator finden dich weiterhin in der App.',
  'You are looking at {p}. You can see everything here, but only its own lead can change it.': 'Du siehst {p}. Du kannst alles sehen, aber nur der jeweilige Leiter kann es ändern.',
  'You are looking at this the way the creator sees it. Nothing here can be edited by you.': 'Du siehst das genau so, wie es der Creator sieht. Du kannst hier nichts bearbeiten.',
  'You are not on the board yet. Play any travel game today and you will be tomorrow.': 'Du stehst noch nicht auf dem Board. Spiel heute irgendein Reisespiel, dann bist du morgen dabei.',
  'You are paid by the views your videos bring. Add your first video to start your month.': 'Du wirst nach den Aufrufen deiner Videos bezahlt. Füge dein erstes Video hinzu, um deinen Monat zu starten.',
  'You are paid for the views your videos gain during each calendar month, at the rate on your VIP page. Views from before you added a video, or from before the month began, are not counted.': 'Du wirst für die Views bezahlt, die deine Videos in jedem Kalendermonat gewinnen, zum Satz auf deiner VIP-Seite. Views von vor dem Hinzufügen eines Videos oder vor Monatsbeginn zählen nicht.',
  'You are part of the community': 'Du bist Teil der Community',
  'You are reading this the way the creator sees it. Only they can change what it says.': 'Du liest das genau so, wie es der Creator sieht. Nur er selbst kann daran etwas ändern.',
  'You are signed in as': 'Du bist angemeldet als',
  'You are under 18, so a parent or guardian agrees to these terms with you. Add their details; after you accept you get a link to send them, and they confirm it themselves. We only use their details about your membership.': 'Du bist unter 18, deshalb stimmt ein Elternteil oder Vormund diesen Bedingungen mit dir zu. Gib seine Daten an; nach dem Akzeptieren bekommst du einen Link, den du ihm schickst, und er bestätigt selbst. Wir nutzen die Daten nur für deine Mitgliedschaft.',
  'You are under 18, so a parent or guardian agrees to these terms with you. Add their details; we only use them about your membership.': 'Da du unter 18 bist, stimmen deine Eltern oder dein Vormund diesen Bedingungen mit dir zu. Gib ihre Daten an; wir nutzen sie nur für deine Mitgliedschaft.',
  'You are warned when the month is on pace to reach 80% of it.': 'Du wirst gewarnt, wenn der Monat auf Kurs ist, 80 % davon zu erreichen.',
  'You award it': 'Du vergibst es',
  'You both entered the same collab post, so you both earn the collab points. Its views count once.': 'Ihr habt beide denselben Collab-Beitrag eingetragen, also bekommt ihr beide die Collab-Punkte. Die Views zählen nur einmal.',
  'You both speak {langs}.': 'Ihr sprecht beide {langs}.',
  'You can add it later from Settings.': 'Du kannst es später in den Einstellungen ergänzen.',
  'You can claim this bonus {n} times for a maximum of {p} points': 'Du kannst diesen Bonus {n}-mal erhalten, maximal {p} Punkte',
  'You can claim this bonus on {n} platforms for a maximum of {p} points': 'Du kannst diesen Bonus für {n} Plattformen erhalten, maximal {p} Punkte',
  'You can claim this bonus on {n} videos for a maximum of {p} points': 'Du kannst diesen Bonus für {n} Videos erhalten, maximal {p} Punkte',
  'You can earn this with {n} different creators for a maximum of {p} points': 'Das kannst du mit {n} verschiedenen Creators verdienen, maximal {p} Punkte',
  'You can read this again any time in Settings > Agreements.': 'Du kannst das jederzeit unter Einstellungen > Vereinbarungen nachlesen.',
  'You can see this market\'s content. Only its own lead, or the owner, can change it.': 'Du kannst die Inhalte dieses Marktes sehen. Nur sein Leiter oder der Inhaber kann sie ändern.',
  'You can set this permanently in Settings.': 'Du kannst das in den Einstellungen dauerhaft festlegen.',
  'You confirmed the {t} for {c} on {d}. They have been told. You can close this page.': 'Du hast die {t} für {c} am {d} bestätigt. {c} wurde informiert. Du kannst diese Seite schließen.',
  'You could be the first to explore it. Add it to your travels once you go, and the next creator planning this trip will find you here.': 'Du könntest der oder die Erste sein, die es erkundet. Trag es nach deiner Reise bei deinen Trips ein, dann findet dich der nächste Creator, der diese Reise plant, genau hier.',
  'You did not enter this challenge.': 'Du hast bei dieser Challenge nicht teilgenommen.',
  'You earned a VIP bonus': 'Du hast einen VIP-Bonus verdient',
  'You got there after the first {n} places were taken.': 'Du warst dran, als die ersten {n} Plätze schon weg waren.',
  'You had these on. Your phone is blocking them now, so you are missing challenge deadlines, replies and results.': 'Du hattest das an. Dein Handy blockiert es jetzt, also verpasst du Challenge-Deadlines, Antworten und Ergebnisse.',
  'You have already asked to join {market}. The team will let you know.': 'Du hast bereits angefragt, {market} beizutreten. Das Team meldet sich bei dir.',
  'You have been invited to {programme}. Create your account and tell us about you.': 'Du wurdest zu {programme} eingeladen. Erstell dein Konto und erzähl uns von dir.',
  'You have been invited. Create your account and tell us about you.': 'Du wurdest eingeladen. Erstelle dein Konto und erzähl uns von dir.',
  'You have been on': 'Du warst auf',
  'You have both been to {places}.': 'Ihr wart beide in {places}.',
